const raw = String($input.first().json.domain || '').trim().toLowerCase()
  .replace(/^[a-z]+:\/\//, '').replace(/[\/?#].*$/, '').replace(/\.$/, '');
const re = /^(?=.{4,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
if (!re.test(raw)) {
  throw new Error('Invalid domain "' + raw + '". Provide a bare domain such as example.com.');
}
return [{ json: { domain: raw } }];

const HIGH_RISK = {23:'Telnet',111:'rpcbind',135:'MS-RPC',139:'NetBIOS',445:'SMB',1433:'MSSQL',1521:'Oracle DB',2049:'NFS',2375:'Docker API (plaintext)',2376:'Docker API (TLS)',3306:'MySQL',3389:'RDP',5432:'PostgreSQL',5900:'VNC',5984:'CouchDB',6379:'Redis',9200:'Elasticsearch',9300:'Elasticsearch transport',11211:'Memcached',27017:'MongoDB'};
const MEDIUM_RISK = {21:'FTP',110:'POP3 (cleartext)',143:'IMAP (cleartext)',389:'LDAP',5601:'Kibana',9090:'Admin/metrics UI'};
const LOW_RISK = {22:'SSH',25:'SMTP',53:'DNS'};
const LEVELS = ['none', 'info', 'low', 'medium', 'high', 'critical'];
const SEVS = ['critical', 'high', 'medium', 'low', 'info', 'unknown'];

function summarize(assets) {
  const sev = { critical: 0, high: 0, medium: 0, low: 0, info: 0, unknown: 0 };
  let level = 'none';
  const bump = (l) => { if (LEVELS.indexOf(l) > LEVELS.indexOf(level)) level = l; };
  const reasons = [];
  const svcMap = new Map();
  const openAll = new Set();
  const tlsIssues = [];
  const findings = [];
  const dangling = [];
  let live = 0, resolved = 0;

  for (const a of assets) {
    if (a.status === 'live') live++;
    if (a.status === 'live' || a.status === 'resolved') resolved++;
    if (a.dns && a.dns.dangling_cname) dangling.push(a.host);

    for (const ipr of ((a.port_scanning && a.port_scanning.ips) || [])) {
      for (const p of (ipr.open_ports || [])) {
        openAll.add(ipr.ip + ':' + p.port);
        const risk = HIGH_RISK[p.port] ? 'high' : MEDIUM_RISK[p.port] ? 'medium' : LOW_RISK[p.port] ? 'low' : null;
        if (!risk) continue;
        const key = ipr.ip + ':' + p.port;
        if (!svcMap.has(key)) {
          svcMap.set(key, {
            ip: ipr.ip, port: p.port,
            service: p.service || HIGH_RISK[p.port] || MEDIUM_RISK[p.port] || LOW_RISK[p.port],
            product: [p.product, p.version].filter(Boolean).join(' ') || null,
            risk, hosts: [],
          });
        }
        svcMap.get(key).hosts.push(a.host);
      }
    }

    for (const c of ((a.tls && a.tls.certificates) || [])) {
      const issues = [];
      if (c.expired) issues.push('expired');
      if (c.self_signed) issues.push('self-signed');
      if (c.mismatched) issues.push('hostname mismatch');
      if (c.untrusted && !c.self_signed) issues.push('untrusted chain');
      if (!c.expired && typeof c.days_to_expiry === 'number' && c.days_to_expiry >= 0 && c.days_to_expiry <= 14) {
        issues.push('expires in ' + c.days_to_expiry + ' days');
      }
      if (issues.length) tlsIssues.push({ host: a.host, port: c.port, issues });
    }

    for (const f of ((a.nuclei && a.nuclei.findings) || [])) {
      const s = SEVS.includes(f.severity) ? f.severity : 'unknown';
      sev[s]++;
      findings.push({ host: a.host, template_id: f.template_id, name: f.name, severity: s, matched_at: f.matched_at, cve: f.cve || [] });
    }
  }

  const services = Array.from(svcMap.values());
  const hi = services.filter((s) => s.risk === 'high');
  const med = services.filter((s) => s.risk === 'medium');
  const lo = services.filter((s) => s.risk === 'low');
  const fmt = (arr) => arr.slice(0, 5).map((s) => s.service + ' on ' + s.ip + ':' + s.port).join(', ');

  if (live > 0) bump('info');
  if (sev.critical) { bump('critical'); reasons.push(sev.critical + ' critical Nuclei finding(s)'); }
  if (sev.high) { bump('high'); reasons.push(sev.high + ' high-severity Nuclei finding(s)'); }
  if (sev.medium) { bump('medium'); reasons.push(sev.medium + ' medium-severity Nuclei finding(s)'); }
  if (sev.low) { bump('low'); reasons.push(sev.low + ' low-severity Nuclei finding(s)'); }
  if (hi.length) { bump('high'); reasons.push(hi.length + ' high-risk service(s) reachable from the internet: ' + fmt(hi)); }
  if (med.length) { bump('medium'); reasons.push(med.length + ' medium-risk service(s) reachable: ' + fmt(med)); }
  if (lo.length) { bump('low'); reasons.push(lo.length + ' management/infrastructure service(s) reachable: ' + fmt(lo)); }
  if (tlsIssues.length) { bump('low'); reasons.push(tlsIssues.length + ' TLS certificate issue(s), e.g. ' + tlsIssues[0].host + ':' + tlsIssues[0].port + ' (' + tlsIssues[0].issues.join(', ') + ')'); }
  if (dangling.length) { bump('low'); reasons.push(dangling.length + ' dangling CNAME(s) (possible subdomain-takeover candidates, needs manual verification): ' + dangling.slice(0, 3).join(', ')); }
  if (!reasons.length) {
    reasons.push(live > 0
      ? live + ' live web host(s) are internet-facing; no risky services, TLS problems or Nuclei findings were detected within the scan profile'
      : 'No live hosts were found for this domain');
  }

  const verdict = ['critical', 'high', 'medium'].includes(level) ? 'EXPOSED'
    : level === 'low' ? 'LIMITED_EXPOSURE'
    : level === 'info' ? 'INTERNET_FACING_ONLY'
    : 'NO_EXPOSURE_FOUND';

  return {
    verdict,
    exposure_level: level,
    reasons,
    stats: {
      assets: assets.length, live_hosts: live, resolved_hosts: resolved,
      open_ports_total: openAll.size, risky_services: services.length,
      tls_issues: tlsIssues.length, dangling_cnames: dangling.length, nuclei: sev,
    },
    risky_services: services.sort((x, y) => LEVELS.indexOf(y.risk) - LEVELS.indexOf(x.risk)).slice(0, 20),
    tls_issues: tlsIssues.slice(0, 10),
    top_findings: findings.sort((x, y) => SEVS.indexOf(x.severity) - SEVS.indexOf(y.severity)).slice(0, 15),
    caveat: 'Coverage is limited to the enabled enumeration sources, the targeted nmap port list and the Nuclei severity/template profile. No findings is not proof of no risk.',
  };
}

const domain = $('Validate Domain').first().json.domain;
const run = $('Find Last Scan Run').all().map((i) => i.json).find((j) => j && j.scan_id) || null;
const assets = $input.all().map((i) => i.json).filter((j) => j && j.host);

let lastTime = null;
if (run) lastTime = run.finished_at || run.updated_at || run.started_at || null;
else if (assets.length) lastTime = assets.map((a) => a.last_seen).filter(Boolean).sort().pop() || null;
const ageH = lastTime ? Math.round((Date.now() - new Date(lastTime).getTime()) / 360000) / 10 : null;
const previously = !!(run || assets.length);

let recommendation;
if (!previously) recommendation = 'No stored data for this domain. A new scan needs explicit user approval.';
else if (ageH !== null && ageH < 24) recommendation = 'Stored data is recent (<24h). You can answer from it; a rescan still requires explicit approval.';
else recommendation = 'Stored data is older than 24h. Offer a refresh scan (requires explicit approval) or answer from stored data.';

let runNote = null;
if (run && run.status === 'running') {
  const h = (Date.now() - new Date(run.started_at).getTime()) / 3.6e6;
  runNote = h > 6 ? 'Last scan was started but never completed (abandoned).' : 'A scan is currently in progress or did not finish.';
}

return [{ json: {
  ok: true,
  domain,
  previously_scanned: previously,
  last_scan_time: lastTime,
  last_scan_age_hours: ageH,
  last_scan: run ? { scan_id: run.scan_id, status: run.status, stage: run.stage, started_at: run.started_at, finished_at: run.finished_at || null, note: runNote } : null,
  asset_count: assets.length,
  stored_summary: assets.length ? summarize(assets) : null,
  recommendation,
} }];
